const terrain=(x,z)=>Math.sin(x*.078+z*.035)*.7+Math.sin(z*.12-x*.06)*.35+Math.sin(x*.24)*.16;
const norm=(a)=>{let l=Math.hypot(...a)||1;return a.map(v=>v/l)};let basis={};function updateCamera(dt){const tx=player.x, tz=player.z;let ideal={x:tx,y:terrain(tx,tz)+8.7,z:tz+13.8};let k=1-Math.exp(-dt*4);camera.x+=(ideal.x-camera.x)*k;camera.y+=(ideal.y-camera.y)*k;camera.z+=(ideal.z-camera.z)*k;const target={x:tx,y:terrain(tx,tz)+1.55,z:tz-2.6};let f=norm([target.x-camera.x,target.y-camera.y,target.z-camera.z]),r=norm([f[2],0,-f[0]]),u=norm([-r[1]*f[2]+r[2]*f[1],r[2]*f[0]-r[0]*f[2],r[0]*f[1]-r[1]*f[0]]);basis={f,r,u,target}}
