function drawTree(t){let y=terrain(t.x,t.z),base=project(t.x,y,t.z);if(!base||base.x<-60||base.x>W+60||base.y<-100||base.y>H+120)return;let s=base.s*t.size;const bi=biome(t.z),col=bi===0?['#405b42','#536c46','#718259']:bi===1?['#203f39','#285047','#466c56']:['#433a37','#67483b','#8b5a41'];let trunk=project(t.x,y+2.3*t.size,t.z);if(!trunk)return;let w=s*1.1;ctx.fillStyle=bi===2?'#362a28':'#493d2d';ctx.fillRect(base.x-w*.18,trunk.y,w*.36,base.y-trunk.y);for(let k=0;k<3;k++){let yy=trunk.y+s*(k*.55),ww=s*(1.55-k*.3),hh=s*1.05;polygon([{x:base.x,y:yy-hh},{x:base.x-ww,y:yy+hh*.24},{x:base.x+ww,y:yy+hh*.24}],col[(k+Math.floor(t.x))%3<0?0:(k+Math.floor(t.x))%3]);}if(bi===1){ctx.globalAlpha=.18;ctx.fillStyle='#a1d9a2';ctx.beginPath();ctx.arc(base.x,base.y-s*1.15,s*.8,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1}}
