function drawFlora(){let all=flora.filter(t=>Math.abs(t.z-player.z)<155).sort((a,b)=>b.z-a.z);for(let t of all){if(t.type<.74)drawTree(t);else drawRock(t.x,t.z,.9+t.size*.3,t.type>.91?'#74635a':'#777b66')}}
function drawAvatar(){let y=terrain(player.x,player.z),p=project(player.x,y,player.z);if(!p)return;let s=Math.max(.6,Math.min(1.7,p.s*17));let bob=Math.sin(time*8)*1.3,px=p.x,feet=p.y;ctx.save();ctx.translate(px,feet);ctx.scale(s,s);ctx.fillStyle='#06110fcc';ctx.beginPath();ctx.ellipse(0,0,13,4,0,0,Math.PI*2);ctx.fill();let cloak=ctx.createLinearGradient(-9,-42,10,-4);cloak.addColorStop(0,'#2b5050');cloak.addColorStop(.55,'#1c3439');cloak.addColorStop(1,'#111f25');polygon([{x:-8,y:-34+bob},{x:8,y:-34+bob},{x:13,y:-7},{x:0,y:-4},{x:-13,y:-8}],cloak,'#b3a468',1);ctx.fillStyle='#d5b576';ctx.beginPath();ctx.ellipse(0,-39+bob,6,7,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#172327';ctx.beginPath();ctx.arc(0,-42+bob,7,Math.PI,Math.PI*2);ctx.fill();ctx.fillRect(-6,-43+bob,12,4);ctx.strokeStyle='#e3d39c';ctx.lineWidth=1.6;ctx.beginPath();ctx.moveTo(-2,-30+bob);ctx.lineTo(1,-15);ctx.stroke();if(player.attack>0){ctx.globalAlpha=Math.min(1,player.attack*2);ctx.strokeStyle='#f8df99';ctx.lineWidth=3;ctx.shadowBlur=15;ctx.shadowColor='#efd475';ctx.beginPath();ctx.arc(0,-24,25,-1.7,1.3);ctx.stroke()}if(player.ward>0){ctx.globalAlpha=.6;ctx.strokeStyle='#8fe5eb';ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(0,-22,19,25,0,0,Math.PI*2);ctx.stroke()}ctx.restore();for(let tr of player.trail){let q=project(tr.x,terrain(tr.x,tr.z)+.1,tr.z);if(q){ctx.fillStyle=`rgba(104,222,221,${tr.life*.22})`;ctx.beginPath();ctx.arc(q.x,q.y,5*q.s*4,0,Math.PI*2);ctx.fill()}}}
function drawEnemy(e){if(!e.alive)return;let p=project(e.x,terrain(e.x,e.z)+.7+Math.sin(time*3+e.phase)*.18,e.z);if(!p||p.x<-80||p.x>W+80||p.y<-80||p.y>H+80)return;let s=p.s*(e.type==='regent'?38:27),col=e.type==='regent'?'#9b3b3e':'#586c69';ctx.save();ctx.translate(p.x,p.y);ctx.globalAlpha=.82;ctx.fillStyle='#091111bb';ctx.beginPath();ctx.ellipse(0,s*.65,s*.57,s*.14,0,0,Math.PI*2);ctx.fill();ctx.shadowBlur=e.type==='regent'?22:12;ctx.shadowColor=e.type==='regent'?'#d35c43':'#78d8c8';ctx.fillStyle=col;ctx.beginPath();ctx.ellipse(0,0,s*.48,s*.67,Math.sin(time+e.phase)*.06,0,Math.PI*2);ctx.fill();ctx.fillStyle='#c9d2bd';ctx.beginPath();ctx.arc(0,-s*.55,s*.33,0,Math.PI*2);ctx.fill();ctx.fillStyle='#172526';ctx.beginPath();ctx.ellipse(0,-s*.68,s*.42,s*.2,0,Math.PI,Math.PI*2);ctx.fill();ctx.fillStyle=e.type==='regent'?'#ff8b57':'#9af2d6';ctx.shadowBlur=12;ctx.shadowColor=ctx.fillStyle;ctx.fillRect(-s*.19,-s*.58,s*.1,s*.06);ctx.fillRect(s*.09,-s*.58,s*.1,s*.06);ctx.restore();if(e.hit>0){ctx.strokeStyle='#fff0c9';ctx.lineWidth=2;ctx.beginPath();ctx.arc(p.x,p.y,s*.6,0,Math.PI*2);ctx.stroke()}if(e.hp<e.max){ctx.fillStyle='#1b1010';ctx.fillRect(p.x-s*.5,p.y-s*.98,s,s*.1);ctx.fillStyle='#de6b5b';ctx.fillRect(p.x-s*.5,p.y-s*.98,s*e.hp/e.max,s*.1)}}
const factions=[{id:'human',name:'Grand Duchy of Man',short:'Human',x:3,z:-9,color:'#d4b568',blurb:'The border duchy watches the western road. Its knights trade protection for favors.'},{id:'elf',name:'Elven Sovereignty',short:'Elven',x:-5,z:-46,color:'#91d5b1',blurb:'The canopy court distrusts strangers. Their ley-fire is old as the first forest.'},{id:'dwarf',name:'Dwarven Clans',short:'Dwarven',x:32,z:-77,color:'#e49a5d',blurb:'Below the mountain, the Irondeep clans turn magma and stone into impossible craft.'},{id:'goblin',name:'Goblin Freeclans',short:'Goblin',x:-31,z:-97,color:'#b9cb77',blurb:'Scrap-lords rule the badlands with volatile cleverness and an unpredictable grin.'}];let standings={human:0,elf:0,dwarf:0,goblin:0};
function drawSettlement(f){let y=terrain(f.x,f.z),p=project(f.x,y,f.z);if(!p||p.x<-180||p.x>W+180||p.y<-250||p.y>H+140)return;let s=p.s,c=f.id;ctx.save();ctx.translate(p.x,p.y);if(c==='human'){let w=46*s,h=19*s;polygon([{x:-w,y:0},{x:-w,y:-h},{x:w,y:-h},{x:w,y:0}], '#887c64','#d3c29188',1);for(let q=-1;q<=1;q+=2){ctx.fillStyle='#a39474';ctx.fillRect(q*w*.72-6*s,-45*s,12*s,45*s);polygon([{x:q*w*.72-8*s,y:-45*s},{x:q*w*.72,y:-56*s},{x:q*w*.72+8*s,y:-45*s}], '#6b6654')}ctx.fillStyle='#c08b58';ctx.fillRect(-16*s,-30*s,32*s,30*s);polygon([{x:-20*s,y:-29*s},{x:0,y:-45*s},{x:20*s,y:-29*s}], '#673e35');ctx.fillStyle='#f1cb79';ctx.fillRect(-3*s,-14*s,6*s,14*s)}if(c==='elf'){let ht=74*s;ctx.fillStyle='#634f3b';ctx.beginPath();ctx.moveTo(-12*s,0);ctx.lineTo(-8*s,-ht*.76);ctx.lineTo(-3*s,-ht);ctx.lineTo(3*s,-ht);ctx.lineTo(11*s,0);ctx.fill();for(let i=0;i<4;i++){let yy=-ht*(.5+i*.12),rx=(26+i%2*13)*s;ctx.strokeStyle='#755f42';ctx.lineWidth=4*s;ctx.beginPath();ctx.moveTo(-7*s,yy+11*s);ctx.quadraticCurveTo(-rx*.65,yy-3*s,-rx,yy-27*s);ctx.moveTo(7*s,yy+7*s);ctx.quadraticCurveTo(rx*.7,yy-5*s,rx,yy-28*s);ctx.stroke()}ctx.shadowBlur=22*s;ctx.shadowColor='#80ddb6';ctx.fillStyle='#326f62';ctx.beginPath();ctx.ellipse(0,-ht*.92,38*s,24*s,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#4d9b78';ctx.beginPath();ctx.ellipse(-12*s,-ht*.98,24*s,18*s,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#e2d38c';ctx.fillRect(-14*s,-25*s,28*s,3*s);ctx.fillStyle='#f4dd96';ctx.fillRect(-2*s,-23*s,4*s,10*s)}if(c==='dwarf'){polygon([{x:-47*s,y:0},{x:-40*s,-45*s},{x:-19*s,-73*s},{x:0,y:-84*s},{x:19*s,-73*s},{x:40*s,-45*s},{x:47*s,y:0}], '#474546','#a4998066');polygon([{x:-18*s,y:0},{x:-16*s,-27*s},{x:-12*s,-43*s},{x:0,y:-52*s},{x:12*s,-43*s},{x:16*s,-27*s},{x:18*s,y:0}], '#171b1b','#cf784c');let glow=ctx.createRadialGradient(0,-14*s,1,0,-14*s,30*s);glow.addColorStop(0,'#ffb45caa');glow.addColorStop(1,'#f77d2500');ctx.fillStyle=glow;ctx.fillRect(-38*s,-56*s,76*s,55*s);ctx.fillStyle='#d8844d';ctx.fillRect(-3*s,-22*s,6*s,22*s)}if(c==='goblin'){for(let i=0;i<4;i++){let xx=(i-1.5)*18*s,yy=(i%2)*-4*s;ctx.fillStyle=i%2?'#574b35':'#686047';ctx.fillRect(xx-7*s,yy-20*s,14*s,20*s);polygon([{x:xx-10*s,y:yy-20*s},{x:xx,y:yy-31*s},{x:xx+10*s,y:yy-20*s}], i%2?'#954d36':'#80734c');ctx.fillStyle='#ff9d43';ctx.shadowBlur=8*s;ctx.shadowColor='#ff6c30';ctx.fillRect(xx-2*s,yy-13*s,4*s,5*s)}ctx.strokeStyle='#8b7b56';ctx.lineWidth:2*s;ctx.beginPath();ctx.moveTo(-38*s,-4*s);ctx.lineTo(35*s,-4*s);ctx.stroke()}ctx.restore();drawNpc(f,p)}
function drawNpc(f,p){let s=p.s*24,near=Math.hypot(player.x-f.x,player.z-f.z)<6;ctx.save();ctx.translate(p.x+(f.id==='elf'?12:0),p.y);ctx.fillStyle='#070e0dcc';ctx.beginPath();ctx.ellipse(0,0,s*.45,s*.13,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=f.id==='human'?'#9c7658':f.id==='elf'?'#79aa83':f.id==='dwarf'?'#aa6445':'#88a249';ctx.beginPath();ctx.ellipse(0,-s*.57,s*.32,s*.56,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#e0c596';ctx.beginPath();ctx.arc(0,-s*1.14,s*.26,0,Math.PI*2);ctx.fill();ctx.fillStyle=f.color;ctx.shadowColor=f.color;ctx.shadowBlur=9;ctx.fillRect(-s*.1,-s*1.16,s*.2,s*.06);if(near){ctx.shadowBlur=0;ctx.fillStyle='#f2dfa9';ctx.font=`${Math.max(10,s*.65)}px Georgia`;ctx.textAlign='center';ctx.fillText('E  ·  SPEAK',0,-s*1.65)}ctx.restore()}
function drawWorld(){drawSky();drawGround();for(let a of anchors)if(!a.got)drawRune(a.x,a.z,a.z*.1,false);for(let p of pickups)if(!p.taken)drawRune(p.x,p.z,p.phase,true);for(let f of factions)drawSettlement(f);drawFlora();for(let e of enemies)drawEnemy(e);drawAvatar();if(shake>0){ctx.fillStyle=`rgba(210,69,55,${shake*.06})`;ctx.fillRect(0,0,W,H)}}

