function drawWorld(){drawSky();drawGround();for(let a of anchors)if(!a.got)drawRune(a.x,a.z,a.z*.1,false);for(let p of pickups)if(!p.taken)drawRune(p.x,p.z,p.phase,true);for(let f of factions)drawSettlement(f);drawFlora();for(let e of enemies)drawEnemy(e);drawAvatar();if(shake>0){ctx.fillStyle=`rgba(210,69,55,${shake*.06})`;ctx.fillRect(0,0,W,H)}}
const modal=document.getElementById('modal'),modalTitle=document.getElementById('modalTitle'),modalText=document.getElementById('modalText'),modalActions=document.getElementById('modalActions'),modalEyebrow=document.getElementById('modalEyebrow');function showModal(title,text,eyebrow,buttons){modalTitle.textContent=title;modalText.textContent=text;modalEyebrow.textContent=eyebrow;modalActions.innerHTML='';for(let b of buttons){let el=document.createElement('button');el.className='button '+(b.secondary?'secondary':'');el.textContent=b.label;el.onclick=b.action;modalActions.append(el)}modal.classList.add('show');modalOpen=true}function hideModal(){modal.classList.remove('show');modalOpen=false}
function showToast(msg){let el=document.getElementById('toast');el.textContent=msg;el.classList.add('show');toastTimer=2.7}
function nearbyEnemy(range=6){let best=null,dist=range;for(let e of enemies){if(!e.alive||e.type==='regent'&&player.anchors<3)continue;let d=Math.hypot(e.x-player.x,e.z-player.z);if(d<dist){best=e;dist=d}}return best}
function damageEnemy(e,n){if(!e||!e.alive)return;e.hp-=n;e.hit=.22;player.attack=.25;shake=.45;if(e.hp<=0){e.alive=false;player.xp+=e.type==='regent'?45:18;player.renown+=e.type==='regent'?10:2;player.shards+=e.type==='regent'?5:1;player.kills++;showToast(e.type==='regent'?'The Ashen Regent falls — Aethelgard is yours to shape.':`Shade banished  ·  +${e.type==='regent'?45:18} essence`);if(e.type==='regent'){ended=true;document.getElementById('questTitle').textContent='The Rift Falls Silent';document.getElementById('questDesc').textContent='Aethelgard remembers the Wayfarer. Its kingdoms will tell a different tale depending on what you choose next.';showModal('The world remembers','The Ashen Regent is undone. You could unite the four peoples, rule them through fear, or walk beyond the maps. Your legend has only just begun.','Chronicle complete',[{label:'Keep exploring',action:()=>hideModal()},{label:'New chronicle',secondary:true,action:()=>location.reload()}])}}}
function useSlot(slot){activeSlot=slot;document.querySelectorAll('.slot').forEach((el,i)=>el.classList.toggle('active',i===slot));if(!started||modalOpen)return;if(slot===0){let e=nearbyEnemy(5.5);if(e){damageEnemy(e,player.power||1);player.mana=Math.min(100,player.mana+2)}else{player.attack=.18;showToast('Your blade cuts through the air.')}}if(slot===1){if(player.mana<20){showToast('Not enough mana.');return}player.mana-=20;let target=nearbyEnemy(24);if(target){let d=Math.hypot(target.x-player.x,target.z-player.z);if(d<19){damageEnemy(target,3+(player.level>1?1:0));showToast('STARFALL  ·  a shard of the old sky');return}}showToast('Starfall blooms into empty air.')}if(slot===2){if(player.mana<15){showToast('Not enough mana.');return}player.mana-=15;let dx=(keys.KeyD||mobileDirs.right?1:0)-(keys.KeyA||mobileDirs.left?1:0),dz=(keys.KeyS||mobileDirs.down?1:0)-(keys.KeyW||mobileDirs.up?1:0);if(!dx&&!dz){dx=Math.sin(player.face);dz=Math.cos(player.face)}let l=Math.hypot(dx,dz)||1;player.x+=dx/l*8;player.z+=dz/l*8;player.invuln=.7;player.dodge=.3;player.trail.push({x:player.x-dx/l*4,z:player.z-dz/l*4,life:1});showToast('VEILSTEP  ·  slip between heartbeats')}if(slot===3){if(player.mana<25){showToast('Not enough mana.');return}player.mana-=25;player.ward=5;player.invuln=.4;showToast('WARD OF THE WAYFARER  ·  5 seconds')}}
function factionTalk(f){let n=standings[f.id];let rank=n>=6?'Honored':n>=3?'Trusted':n<=-3?'Shunned':'Unproven';let options=[{label:'Offer your aid  ·  +2 standing',action:()=>{standings[f.id]+=2;player.renown++;hideModal();showToast(`${f.short} standing increased  ·  ${rank} → ${standings[f.id]>=3?'Trusted':'Known'}`)}}];if(player.shards>=2)options.push({label:'Trade 2 echo shards  ·  +1 standing',secondary:true,action:()=>{player.shards-=2;standings[f.id]++;player.roots++;hideModal();showToast('Trade complete  ·  received brightroot') }});if(f.id==='dwarf')options.push({label:'Forge a runebound edge  ·  3 shards + root',secondary:true,action:()=>{if(player.shards>=3&&player.roots>=1){player.shards-=3;player.roots--;player.power=(player.power||1)+1;hideModal();showToast('Runebound edge forged  ·  blade damage increased')}else{modalText.textContent='The smith needs three echo shards and one brightroot. Gather the scattered resources, then return to the forge.'}}});options.push({label:'Leave',secondary:true,action:hideModal});showModal(f.name,`${f.blurb} Current standing: ${rank} (${n>=0?'+':''}${n}). Your choices shift who trusts the Wayfarer.`, 'Faction encounter',options)}
function interact(){for(let f of factions){if(Math.hypot(player.x-f.x,player.z-f.z)<6){factionTalk(f);return}}for(let a of anchors){if(!a.got&&Math.hypot(player.x-a.x,player.z-a.z)<4.4){a.got=true;player.anchors++;player.xp+=30;player.mana=100;player.renown+=3;showToast(`Echo-anchor attuned  ·  ${player.anchors}/3`);updateQuest();return}}for(let p of pickups){if(!p.taken&&Math.hypot(player.x-p.x,player.z-p.z)<3.4){p.taken=true;if(p.type==='root'){player.roots++;showToast('Brightroot gathered  ·  restorative alchemy')}else{player.shards++;showToast('Echo shard gathered  ·  rare crafting material')}return}}if(Math.hypot(player.x,player.z+4)<7&&player.anchors<3){showToast('The echo-anchor is somewhere along the old road. Follow the glimmers.');return}showToast('Nothing nearby answers your call.')}
function updateQuest(){let title=document.getElementById('questTitle'),desc=document.getElementById('questDesc'),obj=document.getElementById('objectiveText'),count=document.getElementById('objectiveCount');if(player.anchors<3){title.textContent='A Rift in the Vale';desc.textContent='The old stones are waking. Find the three echo-anchors before the tear between worlds widens.';obj.textContent='Echo-anchors';count.textContent=`${player.anchors} / 3`}else{title.textContent='The Ashen Regent';desc.textContent='The anchors reveal the rift-lord beyond the ash fields. End its siege before the storm consumes the vale.';obj.textContent='Shades banished';count.textContent=`${player.kills} / 5`;let boss=enemies.find(e=>e.type==='regent');if(boss&&boss.alive)document.getElementById('bossbar').classList.add('show');showToast('The Ashen March opens  ·  the Regent awaits to the north')}}
function updateHud(){for(let [id,v] of [['hpFill',player.hp],['mpFill',player.mana]])document.getElementById(id).style.width=Math.max(0,v)+'%';document.getElementById('hpText').textContent=Math.ceil(player.hp);document.getElementById('mpText').textContent=Math.floor(player.mana);document.getElementById('levelText').textContent='LEVEL '+String(player.level).padStart(2,'0');document.getElementById('shardCount').textContent=player.shards;document.getElementById('rootCount').textContent=player.roots;document.getElementById('repCount').textContent=player.renown;document.getElementById('xpFill').style.width=(player.xp%100)+'%';let boss=enemies.find(e=>e.type==='regent');if(boss)document.getElementById('bossFill').style.width=Math.max(0,boss.hp/boss.max*100)+'%';if(player.xp>=player.level*100){player.xp-=player.level*100;player.level++;player.hp=100;player.mana=100;showToast(`LEVEL ${player.level}  ·  vitality and mana restored`)}}
function drawMap(){let w=300,h=300;mctx.clearRect(0,0,w,h);let g=mctx.createRadialGradient(150,145,10,150,150,170);g.addColorStop(0,'#1c3732');g.addColorStop(1,'#111d20');mctx.fillStyle=g;mctx.fillRect(0,0,w,h);mctx.save();mctx.beginPath();mctx.arc(150,150,145,0,Math.PI*2);mctx.clip();mctx.strokeStyle='#bea96f33';mctx.lineWidth=7;mctx.beginPath();for(let i=0;i<30;i++){let z=i*4,wx=Math.sin((player.z-z)*.075)*4-player.x,wy=z;mctx.lineTo(150+wx*2.7,150+wy*2.7)}mctx.stroke();for(let f of factions){let dx=(f.x-player.x)*2.65,dy=(f.z-player.z)*2.65;if(Math.hypot(dx,dy)<138){mctx.fillStyle=f.color;mctx.beginPath();mctx.arc(150+dx,150+dy,4.4,0,Math.PI*2);mctx.fill();mctx.font='9px Georgia';mctx.fillText(f.short,154+dx,147+dy)}}for(let a of anchors)if(!a.got){let dx=(a.x-player.x)*2.65,dy=(a.z-player.z)*2.65;if(Math.hypot(dx,dy)<138){mctx.fillStyle='#8fe4d5';mctx.beginPath();mctx.arc(150+dx,150+dy,3,0,Math.PI*2);mctx.fill()}}mctx.fillStyle='#f1d889';mctx.beginPath();mctx.arc(150,150,4.5,0,Math.PI*2);mctx.fill();mctx.strokeStyle='#fff0c8';mctx.lineWidth=1;mctx.stroke();mctx.restore()}

