57 function useSlot(slot){activeSlot=slot;document.querySelectorAll('.slot').forEach((el,i)=>el.classList.toggle('active',i===slot));if(!started||modalOpen)return;if(slot===0){let e=nearbyEnemy(5.5);if(e){damageEnemy(e,player.power||1);player.mana=Math.min(100,player.mana+2)}else{player.attack=.18;showToast('Your blade cuts through the air.')}}if(slot===1){if(player.mana<20){showToast('Not enough mana.');return}player.mana-=20;let target=nearbyEnemy(24);if(target){let d=Math.hypot(target.x-player.x,target.z-player.z);if(d<19){damageEnemy(target,3+(player.level>1?1:0));showToast('STARFALL  ·  a shard of the old sky');return}}showToast('Starfall blooms into empty air.')}if(slot===2){if(player.mana<15){showToast('Not enough mana.');return}player.mana-=15;let dx=(keys.KeyD||mobileDirs.right?1:0)-(keys.KeyA||mobileDirs.left?1:0),dz=(keys.KeyS||mobileDirs.down?1:0)-(keys.KeyW||mobileDirs.up?1:0);if(!dx&&!dz){dx=Math.sin(player.face);dz=Math.cos(player.face)}let l=Math.hypot(dx,dz)||1;player.x+=dx/l*8;player.z+=dz/l*8;player.invuln=.7;player.dodge=.3;player.trail.push({x:player.x-dx/l*4,z:player.z-dz/l*4,life:1});showToast('VEILSTEP  ·  slip between heartbeats')}if(slot===3){if(player.mana<25){showToast('Not enough mana.');return}player.mana-=25;player.ward=5;player.invuln=.4;showToast('WARD OF THE WAYFARER  ·  5 seconds')}}
